Using the recursions in \eref{in1} and \eref{in2}, $x_{m}(k)$ can be expressed as some non-linear function of the weights in the first $m-1$ layers, and the inputs to the first layer. Since the weights in the $m^{th}$ layer are independent of the inputs to the first layer and the weights in all other layers, the weights in the $m^{th}$ layer will also be independent of any non-linear function of these quantities. Therefore, $W_{m}(i,j)$ is independent of $x_{m}(k)$ for all values of $i, j$ and $k$. Furthermore, since $W_{m}(i,j)$ is independent of $x_{m}(k)$ and $x_{m}(l)$, $W_{m}(i,j)$ will also be independent of $x_{m}(k)x_{m}(l)$\qedsymbol
\linebreak
\newline
Taking expectations in \eref{in1} and using proposition 1, along with the fact that $E({\bf{W}}_{m}(i,j)) = 0$ yields 
\begin{equation} 
r_{m} = E(y_{m}(i)) = \sum\limits_{j=1}^{j=N} E({\bf{W}}_{m}(i,j))E(x_{m}(j)) = 0. \enum{in201}
\end{equation} 
Therefore,  $u_{m}^{2} = Var(y_{m}(i)) = E\left(y_{m}(i)^{2}\right) -  \left(E(y_{m}(i))\right)^{2} = E\left(y_{m}(i)^{2}\right)$. Using \eref{in1},




\begin{equation} 
\begin{split}
u_{m}^{2} &= E\left(\sum\limits_{j=1}^{j=N}{\bf{W}}_{m}(i,j)x_{m}(j)\right)^{2} \\
&= \sum\limits_{j=1}^{j=N} E\left({\bf{W}}_{m}(i,j)^{2}x_{m}(j)^{2}\right)  + 2\sum E\left({\bf{W}}_{m}(i,j)x_{m}(j){\bf{W}}_{m}(k,l)x_{m}(l)\right). \\ \enum{in203}
\end{split}
\end{equation} 
From proposition 1, ${\bf{W}}_{m}(i,j)$ and ${\bf{W}}_{m}(k,l)$ will (a) be independent of each other, and (b) be independent of $x_{m}(j)x_{m}(l)$. Using these results, along with the fact that $E({\bf{W}}_{m}(i,j)) = 0 $ gives 
\newline
\begin{equation} 
E\left({\bf{W}}_{m}(i,j)x_{m}(j){\bf{W}}_{m}(k,l)x_{m}(l)\right) = E({\bf{W}}_{m}(i,j))E({\bf{W}}_{m}(k,l))E(x_{m}(j)x_{m}(l)) = 0. \enum{in2041}
\end{equation}
\newline
Plugging \eref{in2041} into \eref{in203} gives



\begin{equation} 
\begin{split}
u_{m}^{2} &= \sum\limits_{j=1}^{j=N} E\left({\bf{W}}_{m}(i,j)^{2}x_{m}(j)^{2}\right) \\ 
&= \sum\limits_{j=1}^{j=N} E\left({\bf{W}}_{m}(i,j)^{2}\right)E\left(x_{m}(j)^{2}\right) \\  
&= Nv^{2}(s_{m}^{2} + \mu_{m}^{2}) \\ \enum{in204}
\end{split}
\end{equation}
for all $i$. Interestingly, this result holds for any arbitrary covariance structure of the inputs to the $m^{th}$ layer. 

